import 'dart:async';
import 'package:dio/dio.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';
import 'package:socket_io_client/socket_io_client.dart' as sio;
const apiUrl=String.fromEnvironment('API_URL',defaultValue:'http://localhost:4000');
final clientProvider=Provider((ref)=>Dio(BaseOptions(baseUrl:apiUrl)));
void main()=>runApp(const ProviderScope(child:KhojLiveDispatcher()));
class KhojLiveDispatcher extends StatelessWidget{const KhojLiveDispatcher({super.key});@override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'KhojLive Dispatcher',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:Colors.teal)),home:const DispatcherPage());}
class DispatcherPage extends ConsumerStatefulWidget{const DispatcherPage({super.key});@override ConsumerState<DispatcherPage> createState()=>_PageState();}
class _PageState extends ConsumerState<DispatcherPage>{final email=TextEditingController(text:'dispatcher@khojlive.test');final password=TextEditingController();String? token;String? error;List<dynamic> drivers=[],deliveries=[];final Map<String,LatLng> positions={};sio.Socket? socket;Timer? timer;
@override void dispose(){socket?.dispose();timer?.cancel();email.dispose();password.dispose();super.dispose();}
Future<void> login()async{try{final response=await ref.read(clientProvider).post('/auth/login',data:{'email':email.text,'password':password.text});if(response.data['user']['role']!='dispatcher')throw Exception('Not dispatcher');token=response.data['accessToken'] as String;error=null;socket=sio.io(apiUrl,sio.OptionBuilder().setTransports(['websocket']).disableAutoConnect().setAuth({'token':token}).build());socket!.on('driver:location',(data){if(data is Map&&mounted)setState(()=>positions[data['driverId'].toString()]=LatLng((data['lat'] as num).toDouble(),(data['lng'] as num).toDouble()));});socket!.on('delivery:updated',(_)=>refresh());socket!.on('connect',(_)=>refresh());socket!.connect();timer=Timer.periodic(const Duration(seconds:20),(_)=>refresh());await refresh();}catch(e){setState(()=>error='Login failed: $e');}}
Future<void> refresh()async{if(token==null)return;try{final dio=ref.read(clientProvider);final headers=Options(headers:{'Authorization':'Bearer $token'});final d=await dio.get('/drivers',options:headers);final jobs=await dio.get('/deliveries',options:headers);final newPositions=<String,LatLng>{};for(final driver in d.data as List){try{final p=await dio.get('/drivers/${driver['id']}/location',options:headers);if(p.data!=null)newPositions[driver['id'] as String]=LatLng((p.data['lat'] as num).toDouble(),(p.data['lng'] as num).toDouble());}catch(_){}}if(mounted)setState((){drivers=d.data as List;deliveries=jobs.data as List;positions.addAll(newPositions);error=null;});}catch(_){if(mounted)setState(()=>error='Connection lost. Reconnecting...');}}
@override Widget build(BuildContext context){if(token==null)return Scaffold(body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:420),child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.route,size:72,color:Colors.teal),Text('KhojLive Dispatcher',style:Theme.of(context).textTheme.headlineSmall),TextField(controller:email,decoration:const InputDecoration(labelText:'Email')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),if(error!=null)Text(error!,style:const TextStyle(color:Colors.red)),FilledButton(onPressed:login,child:const Text('Sign in'))]))));return Scaffold(appBar:AppBar(title:const Text('KhojLive · Fleet Dashboard'),actions:[IconButton(icon:const Icon(Icons.refresh),onPressed:refresh)]),body:LayoutBuilder(builder:(context,box){final wide=box.maxWidth>850;final map=FlutterMap(options:const MapOptions(initialCenter:LatLng(28.625,77.22),initialZoom:12),children:[TileLayer(urlTemplate:'https://tile.openstreetmap.org/{z}/{x}/{y}.png',userAgentPackageName:'com.khojlive.dispatcher'),MarkerLayer(markers:positions.entries.map((e)=>Marker(point:e.value,width:100,height:60,child:Column(children:[const Icon(Icons.local_shipping,color:Colors.teal),Text(e.key.substring(0,8),style:const TextStyle(fontSize:10))])).toList()),const RichAttributionWidget(attributions:[TextSourceAttribution('© OpenStreetMap contributors')])]);final details=ListView(children:[if(error!=null)ListTile(title:Text(error!,style:const TextStyle(color:Colors.red))),ListTile(title:Text('${drivers.length} drivers'),subtitle:Text('${positions.length} reporting locations')),const Divider(),...drivers.map((d)=>ListTile(leading:const Icon(Icons.local_shipping_outlined),title:Text(d['name']??'Driver'),subtitle:Text('${d['availability']} · ${d['vehicle']??'No vehicle'}'))),const Divider(),...deliveries.map((d)=>ListTile(title:Text(d['tracking_code']),subtitle:Text('${d['pickup']} → ${d['destination']}'),trailing:Chip(label:Text(d['status']))))]);return wide?Row(children:[Expanded(flex:3,child:map),SizedBox(width:360,child:details)]):Column(children:[Expanded(child:map),Expanded(child:details)]); }));}
}
